# ---------------------------------------------------------------- glyphs
_GCACHE = {}


def glyph_alpha(font, ch):
    """Decode a glyph's 4-bit alpha map to bytes (cached)."""
    key = (id(font), ch)
    got = _GCACHE.get(key)
    if got is not None:
        return got
    _adv, _bx, _by, w, h, b85 = font[ch]
    if not b85:
        _GCACHE[key] = b""
        return b""
    packed = base64.b85decode(b85)
    out = bytearray(w * h)
    for i in range(w * h):
        byte = packed[i // 2]
        out[i] = ((byte >> 4) if i % 2 == 0 else (byte & 15)) * 17
    _GCACHE[key] = bytes(out)
    return _GCACHE[key]


def text_width(s, font, em, size, tracking=0.0):
    """Width in logical px of s set at `size` (logical px em)."""
    scale = size * SS / em
    total = 0.0
    for ch in s:
        g = font.get(ch) or font["?"]
        total += g[0] * scale / SS + tracking
    return total - (tracking if s else 0.0)


def wrap_text(s, font, em, size, max_width, tracking=0.0):
    words = s.split(" ")
    lines = []
    cur = ""
    for word in words:
        trial = word if not cur else cur + " " + word
        if text_width(trial, font, em, size, tracking) <= max_width:
            cur = trial
        else:
            if cur:
                lines.append(cur)
            cur = word
    if cur:
        lines.append(cur)
    return lines


# ---------------------------------------------------------------- canvas
class Canvas:
    """Logical W x H canvas stored at SS supersampling."""

    def __init__(self, w, h, bg):
        self.w = w
        self.h = h
        self.dw = w * SS
        self.dh = h * SS
        self.px = bytearray(bg * self.dw * self.dh)

    def set(self, x, y, color):
        if 0 <= x < self.dw and 0 <= y < self.dh:
            i = (y * self.dw + x) * 3
            self.px[i] = color[0]
            self.px[i + 1] = color[1]
            self.px[i + 2] = color[2]

    def blend(self, x, y, color, a):
        if a <= 0 or not (0 <= x < self.dw and 0 <= y < self.dh):
            return
        if a >= 255:
            self.set(x, y, color)
            return
        i = (y * self.dw + x) * 3
        inv = 255 - a
        self.px[i] = (color[0] * a + self.px[i] * inv) // 255
        self.px[i + 1] = (color[1] * a + self.px[i + 1] * inv) // 255
        self.px[i + 2] = (color[2] * a + self.px[i + 2] * inv) // 255

    def rect(self, x, y, w, h, color):
        x, y, w, h = int(x * SS), int(y * SS), int(w * SS), int(h * SS)
        for yy in range(y, y + h):
            for xx in range(x, x + w):
                self.set(xx, yy, color)

    def frame(self, x, y, w, h, color, t=1):
        self.rect(x, y, w, t, color)
        self.rect(x, y + h - t, w, t, color)
        self.rect(x, y, t, h, color)
        self.rect(x + w - t, y, t, h, color)

    def hline(self, x, y, w, color, t=1):
        self.rect(x, y, w, t, color)

    def vline(self, x, y, h, color, t=1):
        self.rect(x, y, t, h, color)

    def vgrad(self, x, y, w, h, top, bottom):
        """Vertical gradient rectangle (logical coords)."""
        x, y, w, h = int(x * SS), int(y * SS), int(w * SS), int(h * SS)
        for yy in range(y, y + h):
            t = (yy - y) / max(1, h - 1)
            c = (int(top[0] + (bottom[0] - top[0]) * t),
                 int(top[1] + (bottom[1] - top[1]) * t),
                 int(top[2] + (bottom[2] - top[2]) * t))
            for xx in range(x, x + w):
                self.set(xx, yy, c)

    def line(self, x0, y0, x1, y1, color, t=1):
        x0, y0, x1, y1 = int(x0 * SS), int(y0 * SS), int(x1 * SS), int(y1 * SS)
        t = max(1, int(round(t * SS)))
        dx = abs(x1 - x0)
        dy = -abs(y1 - y0)
        sx = 1 if x0 < x1 else -1
        sy = 1 if y0 < y1 else -1
        err = dx + dy
        x, y = x0, y0
        while True:
            for oy in range(t):
                for ox in range(t):
                    self.set(x + ox, y + oy, color)
            if x == x1 and y == y1:
                break
            e2 = 2 * err
            if e2 >= dy:
                err += dy
                x += sx
            if e2 <= dx:
                err += dx
                y += sy

    def circle(self, cx, cy, r, color):
        cx, cy, r = int(cx * SS), int(cy * SS), int(r * SS)
        for yy in range(cy - r, cy + r + 1):
            for xx in range(cx - r, cx + r + 1):
                if (xx - cx) ** 2 + (yy - cy) ** 2 <= r * r:
                    self.set(xx, yy, color)

    def ring(self, cx, cy, r, color, t=2):
        cx, cy, r, t = int(cx * SS), int(cy * SS), int(r * SS), int(t * SS)
        for yy in range(cy - r, cy + r + 1):
            for xx in range(cx - r, cx + r + 1):
                d = (xx - cx) ** 2 + (yy - cy) ** 2
                if (r - t) ** 2 <= d <= r * r:
                    self.set(xx, yy, color)

    def triangle(self, x0, y0, x1, y1, x2, y2, color):
        self.polygon([(x0, y0), (x1, y1), (x2, y2)], color)

    def polygon(self, pts, color):
        """Scanline polygon fill (logical coords)."""
        pts = [(x * SS, y * SS) for (x, y) in pts]
        miny = int(min(p[1] for p in pts))
        maxy = int(max(p[1] for p in pts))
        n = len(pts)
        for yy in range(miny, maxy + 1):
            nodes = []
            for i in range(n):
                x0, y0 = pts[i]
                x1, y1 = pts[(i + 1) % n]
                if y0 == y1:
                    continue
                if (yy >= min(y0, y1)) and (yy < max(y0, y1)):
                    nodes.append(x0 + (yy - y0) * (x1 - x0) / (y1 - y0))
            nodes.sort()
            for i in range(0, len(nodes) - 1, 2):
                xa = int(nodes[i])
                xb = int(nodes[i + 1])
                for xx in range(xa, xb + 1):
                    self.set(xx, yy, color)

    # ---- text ----
    def text(self, x, y, s, font, em, asc, size, color, tracking=0.0):
        """Draw text with baseline at logical y; returns x after it."""
        scale = size * SS / em
        cx = x * SS
        baseline = y * SS
        for ch in s:
            g = font.get(ch) or font["?"]
            adv, bx, by, w, h, _b85 = g
            if w and h:
                alpha = glyph_alpha(font, ch)
                gx = cx + bx * scale
                gy = baseline - asc * scale + by * scale
                dw = max(1, int(round(w * scale)))
                dh = max(1, int(round(h * scale)))
                for dy in range(dh):
                    sy = dy / scale
                    iy = int(sy)
                    fy = sy - iy
                    for dx in range(dw):
                        sx = dx / scale
                        ix = int(sx)
                        fx = sx - ix
                        a00 = alpha[iy * w + ix] if iy < h and ix < w else 0
                        a10 = alpha[iy * w + ix + 1] if iy < h and ix + 1 < w else 0
                        a01 = alpha[(iy + 1) * w + ix] if iy + 1 < h and ix < w else 0
                        a11 = alpha[(iy + 1) * w + ix + 1] if iy + 1 < h and ix + 1 < w else 0
                        a = int(a00 * (1 - fx) * (1 - fy) + a10 * fx * (1 - fy)
                                + a01 * (1 - fx) * fy + a11 * fx * fy)
                        if a:
                            self.blend(int(gx) + dx, int(gy) + dy, color, a)
            cx += adv * scale + tracking * SS
        return cx / SS

    def text_center(self, cx, y, s, font, em, asc, size, color,
                    tracking=0.0):
        w = text_width(s, font, em, size, tracking)
        return self.text(cx - w / 2, y, s, font, em, asc, size, color,
                         tracking)

    def text_right(self, right, y, s, font, em, asc, size, color,
                   tracking=0.0):
        w = text_width(s, font, em, size, tracking)
        return self.text(right - w, y, s, font, em, asc, size, color,
                         tracking)

    def para(self, x, y, s, font, em, asc, size, color, max_width,
             leading=None, tracking=0.0):
        """Wrapped paragraph; y is the first baseline; returns y after."""
        if leading is None:
            leading = size * 1.35
        for line in wrap_text(s, font, em, size, max_width, tracking):
            self.text(x, y, line, font, em, asc, size, color, tracking)
            y += leading
        return y

    def downsample(self):
        """Box-filter the supersampled canvas to logical size."""
        out = bytearray(W * H * 3)
        for y in range(H):
            for x in range(W):
                r = g = b = 0
                for oy in range(SS):
                    base = ((y * SS + oy) * self.dw + x * SS) * 3
                    for ox in range(SS):
                        i = base + ox * 3
                        r += self.px[i]
                        g += self.px[i + 1]
                        b += self.px[i + 2]
                n = SS * SS
                j = (y * W + x) * 3
                out[j] = r // n
                out[j + 1] = g // n
                out[j + 2] = b // n
        return out


# ---------------------------------------------------------------- PNG encoder
def png_bytes(raw):
    rows = bytearray()
    stride = W * 3
    for y in range(H):
        rows.append(0)
        start = y * stride
        rows.extend(raw[start:start + stride])
    data = zlib.compress(bytes(rows), 9)

    def chunk(kind, payload):
        out = struct.pack(">I", len(payload)) + kind + payload
        out += struct.pack(">I", zlib.crc32(kind + payload) & 0xFFFFFFFF)
        return out

    ihdr = struct.pack(">IIBBBBB", W, H, 8, 2, 0, 0, 0)
    return (b"\x89PNG\r\n\x1a\n" + chunk(b"IHDR", ihdr)
            + chunk(b"IDAT", data) + chunk(b"IEND", b""))


# ---------------------------------------------------------------- illustrations
# Flat editorial vector style: layered silhouettes, muted palette,
# fine gold detail. All three heroes share the same visual language.

def hero_markets(c, x, y, w, h):
    """Falling market chart over a night skyline."""
    c.vgrad(x, y, w, h, SKY1, NAVY2)
    for i in range(1, 5):
        gy = y + i * h / 5
        c.hline(x + 8, gy, w - 16, (58, 74, 110), 0.7)
    base = y + h - 30
    heights = [0.92, 0.80, 0.68, 0.55, 0.42, 0.30]
    bw = (w - 70) / 6
    tops = []
    for i, f in enumerate(heights):
        bx = x + 22 + i * bw
        bh = f * (h - 54)
        c.rect(bx, base - bh, bw - 12, bh, RED)
        tops.append((bx + (bw - 12) / 2, base - bh - 6))
    for i in range(len(tops) - 1):
        c.line(tops[i][0], tops[i][1], tops[i + 1][0], tops[i + 1][1],
               WHITE, 2.2)
    for (tx, ty) in tops:
        c.circle(tx, ty, 3.2, GOLD)
        c.circle(tx, ty, 1.4, WHITE)
    ax = x + w - 34
    c.line(ax, y + 14, ax, y + 46, BURGUNDY, 5)
    c.triangle(ax - 9, y + 44, ax + 9, y + 44, ax, y + 60, BURGUNDY)
    sky = [(0, 20), (26, 20), (26, 12), (44, 12), (44, 24), (70, 24),
           (70, 14), (96, 14), (96, 26), (128, 26), (128, 16), (156, 16),
           (156, 28), (188, 28), (188, 18), (216, 18), (216, 26),
           (248, 26), (248, 15), (276, 15), (276, 24), (w, 24)]
    pts = [(x + px, y + h) for (px, _t) in sky]
    pts += [(x + px, y + h - t) for (px, t) in reversed(sky)]
    c.polygon(pts, (10, 16, 32))
    wins = [(30, 8), (58, 12), (82, 6), (112, 10), (140, 7), (170, 12),
            (200, 8), (232, 11), (262, 7), (292, 10)]
    for (wx, wy) in wins:
        c.rect(x + wx, y + h - wy - 3, 3, 3, GOLD)


def _flag_pk(c, x, y, w, h):
    c.rect(x, y, w, h, (20, 96, 52))
    c.rect(x, y, w * 0.28, h, WHITE)
    c.circle(x + w * 0.62, y + h * 0.52, h * 0.30, WHITE)
    c.circle(x + w * 0.68, y + h * 0.44, h * 0.26, (20, 96, 52))
    c.circle(x + w * 0.80, y + h * 0.30, 1.6, WHITE)


def _flag_cn(c, x, y, w, h):
    c.rect(x, y, w, h, (178, 34, 44))
    c.circle(x + w * 0.22, y + h * 0.28, 2.2, GOLD)
    for (fx, fy) in [(0.42, 0.14), (0.46, 0.30), (0.46, 0.46),
                     (0.42, 0.60)]:
        c.circle(x + w * fx, y + h * fy, 1.3, GOLD)


def hero_rocket(c, x, y, w, h):
    """Shenzhou-style rocket climbing into a starry dusk."""
    c.vgrad(x, y, w, h, SKY1, SKY2)
    stars = [(18, 12), (52, 30), (88, 10), (120, 26), (150, 8),
             (186, 20), (214, 10), (248, 28), (282, 14), (306, 34),
             (36, 48), (268, 52), (96, 44), (228, 46)]
    for (sx, sy) in stars:
        c.circle(x + sx, y + sy, 1.3, (220, 226, 240))
    cx = x + w / 2
    top = y + 8
    body_w = 26
    c.polygon([(cx - body_w / 2, top + 30), (cx + body_w / 2, top + 30),
               (cx + body_w / 2, top + 70), (cx - body_w / 2, top + 70)],
              WHITE)
    c.triangle(cx - body_w / 2, top + 30, cx + body_w / 2, top + 30,
               cx, top, BURGUNDY)
    c.circle(cx, top + 46, 6, NAVY)
    c.ring(cx, top + 46, 6, GOLD, 1.6)
    c.triangle(cx - body_w / 2, top + 56, cx - body_w / 2 - 14,
               top + 76, cx - body_w / 2, top + 76, BURGUNDY)
    c.triangle(cx + body_w / 2, top + 56, cx + body_w / 2 + 14,
               top + 76, cx + body_w / 2, top + 76, BURGUNDY)
    c.triangle(cx - 8, top + 70, cx + 8, top + 70, cx, top + 98,
               ORANGE)
    c.triangle(cx - 4.5, top + 70, cx + 4.5, top + 70, cx, top + 90,
               GOLD)
    for (sx, sy, sr) in [(-24, 100, 9), (-7, 105, 11), (11, 103, 10),
                         (28, 98, 7)]:
        c.circle(cx + sx, y + sy, sr, (150, 152, 168))
    c.rect(x, y + h - 14, w, 14, (12, 18, 36))
    c.line(x + 30, y + h - 14, x + 30, y + h - 40, TAN, 2)
    _flag_pk(c, x + 32, y + h - 40, 32, 20)
    c.line(x + w - 30, y + h - 14, x + w - 30, y + h - 40, TAN, 2)
    _flag_cn(c, x + w - 62, y + h - 40, 32, 20)


def _palm(c, x, y, h, lean):
    c.line(x, y, x + lean * 0.4, y - h * 0.55, (92, 66, 44), 3)
    c.line(x + lean * 0.4, y - h * 0.55, x + lean, y - h, (92, 66, 44), 2.4)
    tx, ty = x + lean, y - h
    for (dx, dy) in [(-20, -6), (-13, -13), (0, -16), (13, -13),
                     (20, -6), (17, 3), (-17, 3)]:
        c.line(tx, ty, tx + dx, ty + dy, GREEN, 2)


def hero_villa(c, x, y, w, h):
    """Mar-a-Lago style villa at dusk with palms."""
    c.vgrad(x, y, w, h, DUSK1, DUSK2)
    c.circle(x + w - 44, y + 22, 11, GOLD)
    c.circle(x + w - 44, y + 22, 14, (214, 172, 66))
    c.circle(x + w - 44, y + 22, 11, GOLD)
    gy = y + h - 20
    c.rect(x, gy, w, 20, GREEN)
    vx = x + 84
    vw = w - 168
    vy = gy - 48
    c.rect(vx, vy, vw, 48, (242, 236, 222))
    c.triangle(vx - 8, vy, vx + vw + 8, vy, vx + vw / 2, vy - 24,
               BURGUNDY)
    c.rect(vx + vw / 2 - 11, vy - 36, 22, 18, (242, 236, 222))
    c.triangle(vx + vw / 2 - 14, vy - 36, vx + vw / 2 + 14, vy - 36,
               vx + vw / 2, vy - 48, BURGUNDY)
    for i in range(5):
        wx = vx + 12 + i * (vw - 24) / 4 - 5
        c.rect(wx, vy + 9, 10, 13, NAVY)
        c.rect(wx, vy + 27, 10, 11, NAVY)
    c.rect(vx + vw / 2 - 7, vy + 26, 14, 22, BURGUNDY)
    for i in range(4):
        cxx = vx + 16 + i * (vw - 32) / 3
        c.vline(cxx, vy + 4, 44, WHITE, 2.5)
    _palm(c, x + 36, gy + 4, 52, 12)
    _palm(c, x + w - 30, gy + 4, 46, -10)
    c.line(x + 14, gy, x + 14, gy - 44, TAN, 2)
    c.rect(x + 16, gy - 44, 28, 17, NAVY)
    sx, sy = x + 30, gy - 35.5
    c.polygon([(sx, sy - 6), (sx + 1.8, sy - 1.8), (sx + 6, sy),
               (sx + 1.8, sy + 1.8), (sx, sy + 6), (sx - 1.8, sy + 1.8),
               (sx - 6, sy), (sx - 1.8, sy - 1.8)], WHITE)


