def _is_land(lon, lat):
    for (a, b, c0, d) in LAND:
        if a <= lon <= b and c0 <= lat <= d:
            return True
    return False


def draw_map(c, x, y, w, h, pins):
    """Dotted world map with numbered pins and place labels."""
    c.rect(x, y, w, h, (251, 248, 240))
    c.frame(x, y, w, h, HAIR, 1)
    lon0, lon1, lat0, lat1 = -180, 180, 76, -68

    def proj(lon, lat):
        px = x + (lon - lon0) / (lon1 - lon0) * w
        py = y + (lat0 - lat) / (lat0 - lat1) * h
        return px, py

    lon = lon0 + 2
    while lon < lon1:
        lat = lat0 - 2
        while lat > lat1:
            if _is_land(lon, lat):
                px, py = proj(lon, lat)
                c.circle(px, py, 1.25, (96, 112, 138))
            lat -= 4.5
        lon += 4
    for (num, plon, plat, label, dx, dy, pdx, pdy) in pins:
        px, py = proj(plon, plat)
        px, py = px + pdx, py + pdy
        if label:
            lx, ly = px + dx, py + dy
            c.line(px, py, lx, ly - 3, GREY, 0.8)
            c.text(lx, ly, label, SANS, SANS_EM, SANS_ASC, 7.5, INK)
        c.circle(px, py, 5, BURGUNDY)
        c.ring(px, py, 5, WHITE, 1)
        c.text_center(px, py + 2.5, str(num), SANSB, SANSB_EM, SANSB_ASC,
                      7, WHITE)


